package com.finsight.controller; import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*; @RestControllerAdvice public class Errors {@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<?> conflict(IllegalStateException e){return ResponseEntity.status(409).body(Map.of("message",e.getMessage()));}}
